	for _, field := range []string{`"added":[]`, `"removed":[]`, `"changed":[]`} {
		if !bytes.Contains(raw, []byte(field)) {
			t.Fatalf("marshalled diff missing %s: %s", field, raw)
		}
	}
}

// TestCompareDoesNotShareMemory proves isolation in both directions: Compare
